read_all <- function() {
  points <- lapply(
      strsplit(readLines("input/points.csv")[-1L],",",fixed=TRUE),
      function(row) list(id=row[1L],x=as.numeric(row[2L]),y=as.numeric(row[3L]))
  )
  lines <- readLines("input/init.txt")
  initial <- list()
  cursor <- 1L
  while (cursor <= length(lines)) {
    if (!nzchar(lines[cursor])) {
      cursor <- cursor+1L
      next
    }
    k <- as.integer(strsplit(lines[cursor]," ",fixed=TRUE)[[1L]][2L])
    weights <- as.numeric(strsplit(lines[cursor+1L]," ",fixed=TRUE)[[1L]][-1L])
    means <- covariances <- list()
    for (j in seq_len(k)) {
      values <- as.numeric(strsplit(lines[cursor+1L+j]," ",fixed=TRUE)[[1L]][-(1:2)])
      means[[j]] <- values[1:2]
      covariances[[j]] <- values[3:5]
    }
    initial[[as.character(k)]] <- list(weights=weights,means=means,covariances=covariances,type="")
    cursor <- cursor+k+2L
  }
  raw <- list()
  for (words in strsplit(readLines("input/params.txt")," ",fixed=TRUE)) raw[[words[1L]]] <- words[-1L]
  settings <- list(ks=as.integer(raw$K),types=raw$TYPES,iterations=as.integer(raw$ITERATIONS),epsilon=as.numeric(raw$REGULARIZATION),
    settle=as.numeric(raw$SETTLE_TOLERANCE),kmeans_iterations=as.integer(raw$KMEANS_MAX_ITERATIONS),cv_folds=as.integer(raw$CV_FOLDS),
    uncertain=as.numeric(raw$UNCERTAIN_THRESHOLD),low_density=as.numeric(raw$LOW_DENSITY_THRESHOLD),gof_edges=as.numeric(raw$GOF_EDGES),
    map_x=as.numeric(raw$MAP_X),map_y=as.numeric(raw$MAP_Y),map_size=as.integer(raw$MAP_SIZE))
  list(points=points,initial=initial,settings=settings)
}

point_xy <- function(point) c(point$x,point$y)
covariance_type_adjust <- function(initial,type) {
  weights <- initial$weights
  means <- initial$means
  source <- initial$covariances
  if (type == "FULL") {
    covariances <- source
  } else if (type == "DIAG") {
    covariances <- lapply(source,function(cov) c(cov[1L],0,cov[3L]))
  } else if (type == "SPHERICAL") {
    covariances <- lapply(source,function(cov) c((cov[1L]+cov[3L])/2,0,(cov[1L]+cov[3L])/2))
  } else {
    shared <- vapply(
        seq_len(3L),
        function(j) ordered_sum(vapply(seq_along(weights),function(k) weights[k]*source[[k]][j],numeric(1))),
        numeric(1)
    )
    covariances <- replicate(length(weights),shared,simplify=FALSE)
  }
  list(weights=weights,means=means,covariances=covariances,type=type)
}
responsibilities <- function(points,model) {
  records <- list()
  loglik <- 0
  for (point in points) {
    scores <- vapply(
        seq_along(model$weights),
        function(k) weighted_log_density(
            point_xy(point),
            model$weights[k],
            model$means[[k]],
            model$covariances[[k]]
        ),
        numeric(1)
    )
    maximum <- max(scores)
    exponentials <- exp(scores-maximum)
    normalizer <- ordered_sum(exponentials)
    normalized <- exponentials/normalizer
    log_density <- maximum+log(normalizer)
    records[[length(records)+1L]] <- list(responsibilities=normalized,log_density=log_density,scores=scores)
    loglik <- loglik+log_density
  }
  list(records=records,loglik=loglik)
}
update_model <- function(points,records,type,epsilon) {
  n <- length(points)
  k_count <- length(records[[1L]]$responsibilities)
  counts <- vapply(
      seq_len(k_count),
      function(k) ordered_sum(vapply(records,function(row) row$responsibilities[k],numeric(1))),
      numeric(1)
  )
  weights <- counts/n
  means <- lapply(seq_len(k_count),function(k) c(
    ordered_sum(vapply(
        seq_len(n),
        function(i) records[[i]]$responsibilities[k]*points[[i]]$x,
        numeric(1)
    ))/counts[k],
    ordered_sum(vapply(
        seq_len(n),
        function(i) records[[i]]$responsibilities[k]*points[[i]]$y,
        numeric(1)
    ))/counts[k]))
  scatter <- lapply(seq_len(k_count),function(k) {
    a <- b <- c <- 0
    for (i in seq_len(n)) {
      r <- records[[i]]$responsibilities[k]
      dx <- points[[i]]$x-means[[k]][1L]
      dy <- points[[i]]$y-means[[k]][2L]
      a <- a+r*dx*dx
      b <- b+r*dx*dy
      c <- c+r*dy*dy
    }
    c(a,b,c)
  })
  if (type == "TIED") {
    shared <- vapply(seq_len(3L),function(j) ordered_sum(vapply(scatter,`[`,numeric(1),j))/n+if (j == 2L) 0 else epsilon,numeric(1))
    covariances <- replicate(k_count,shared,simplify=FALSE)
  } else covariances <- lapply(seq_len(k_count),function(k) {
    a <- scatter[[k]][1L]
    b <- scatter[[k]][2L]
    c <- scatter[[k]][3L]
    nk <- counts[k]
    if (type == "FULL") return(c(a/nk+epsilon,b/nk,c/nk+epsilon))
    if (type == "DIAG") return(c(a/nk+epsilon,0,c/nk+epsilon))
    variance <- (a/nk+c/nk)/2+epsilon
    c(variance,0,variance)
  })
  list(weights=weights,means=means,covariances=covariances,type=type)
}
run_em <- function(points,initial,type,iterations,epsilon) {
  model <- covariance_type_adjust(initial,type)
  step <- responsibilities(points,model)
  trace <- step$loglik
  for (unused in seq_len(iterations)) {
    model <- update_model(points,step$records,type,epsilon)
    step <- responsibilities(points,model)
    trace <- c(trace,step$loglik)
  }
  list(model=model,records=step$records,trace=trace,loglik=step$loglik)
}

squared_distance <- function(a,b) {
  dx <- a[1L]-b[1L]
  dy <- a[2L]-b[2L]
  dx*dx+dy*dy
}
distance <- function(a,b) sqrt(squared_distance(a,b))
assignments <- function(points,centers) vapply(
    points,
    function(point) which.min(vapply(
        centers,
        function(center) squared_distance(point_xy(point),center),
        numeric(1)
    )),
    integer(1)
)
run_kmeans <- function(points,initial_centers,max_iterations) {
  centers <- initial_centers
  assigned <- assignments(points,centers)
  iterations <- 0L
  for (t in seq_len(max_iterations)) {
    next_centers <- lapply(seq_along(centers),function(k) {
      members <- points[assigned == k]
      if (!length(members)) return(centers[[k]])
      c(
          ordered_sum(vapply(members,function(p) p$x,numeric(1)))/length(members),
          ordered_sum(vapply(members,function(p) p$y,numeric(1)))/length(members)
      )
    })
    centers <- next_centers
    next_assignment <- assignments(points,centers)
    iterations <- t
    if (identical(next_assignment,assigned)) {
      assigned <- next_assignment
      break
    }
    assigned <- next_assignment
  }
  inertia <- ordered_sum(vapply(
      seq_along(points),
      function(i) squared_distance(point_xy(points[[i]]),centers[[assigned[i]]]),
      numeric(1)
  ))
  list(
      centers=centers,
      assignment=assigned,
      iterations=iterations,
      inertia=inertia,
      sizes=vapply(seq_along(centers),function(k) sum(assigned == k),integer(1))
  )
}

LEVELS <- strsplit(" .:-=+*#%@","",fixed=TRUE)[[1L]]
dec <- function(value,places=4L) {
  text <- sprintf(paste0("%.",places,"f"),value)
  if (startsWith(text,"-") && as.numeric(text) == 0) substring(text,2L) else text
}
optional <- function(value) if (is.null(value)) "-" else dec(value)
real_values <- function(items) paste(vapply(items,dec,character(1)),collapse=" ")
integer_values <- function(items) paste(sprintf("%.0f",items),collapse=" ")
framed <- function(grid) {
  border <- paste0("+",strrep("-",ncol(grid)),"+")
  c(
      border,
      vapply(seq_len(nrow(grid)),function(r) paste0("|",paste(grid[r,],collapse=""),"|"),character(1)),
      border
  )
}
write_lines <- function(name,lines) {
  dir.create("output",showWarnings=FALSE)
  writeLines(lines,file.path("output",name),useBytes=TRUE)
}
write_blocks <- function(name,blocks) {
  lines <- character()
  for (block in blocks) {
    if (length(lines)) lines <- c(lines,"")
    lines <- c(lines,block)
  }
  write_lines(name,lines)
}
